patch:
diff --git a/src/cluster.c b/src/cluster.c
index 11a2b3c..f8e9d0a 100644
--- a/src/cluster.c
+++ b/src/cluster.c
@@ -1050,6 +1050,10 @@ static int clusterManagerMoveSlot(clusterNode *src, clusterNode *dst, int slot)
     }

     /* Check if the destination node has good replicas. */
+    if (server.cluster_allow_replica_migration == 0) {
+        /* If replica migration is disabled, we cannot ensure the destination
+         * has good replicas, so we skip this check to allow rebalancing. */
+    } else if (clusterNodeGetGoodReplicas(dst) == 0) {
         clusterManagerLogWarn("clusterManagerMoveSlot: NOREPLICAS Not enough good replicas to write.\n");
         return C_ERR;
     }
